namespace Ehr.Data.Patients;

// A visit, shaped on FHIR's Encounter. The vital signs taken at it are observations that name it
// (Observation.EncounterId), as FHIR has them; until the expansion plan's step 9 they were columns here.
// PHI: row-level security is enabled and forced on it and every write is recorded by trigger (db/policies); reads go
// through the PHI reader in Ehr.Domain, which records them. Checking a patient in for an appointment creates one
// (Ehr.Domain.Scheduling); nothing updates or deletes one. Synthetic data only.
public class Encounter
{
    // UUIDv7, generated by whoever creates the row.
    public Guid Id { get; set; }

    public Guid PatientId { get; set; }

    // One of EncounterStatus.
    public required string Status { get; set; }

    // One of EncounterClass, or another code from the same HL7 v3 list: FHIR lets that list grow.
    public required string ClassCode { get; set; }

    // Why the patient came, such as "Annual physical".
    public string? Reason { get; set; }

    public DateTimeOffset PeriodStart { get; set; }

    public DateTimeOffset? PeriodEnd { get; set; }
}

// FHIR R4's Encounter status codes, the values Encounter.Status may hold.
public static class EncounterStatus
{
    public const string Planned = "planned";

    public const string Arrived = "arrived";

    public const string Triaged = "triaged";

    public const string InProgress = "in-progress";

    public const string OnLeave = "onleave";

    public const string Finished = "finished";

    public const string Cancelled = "cancelled";

    public const string EnteredInError = "entered-in-error";

    public const string Unknown = "unknown";

    public static readonly string[] All = [Planned, Arrived, Triaged, InProgress, OnLeave, Finished, Cancelled, EnteredInError, Unknown];

    // Visits that haven't happened, or never did.
    public static readonly string[] NotHeld = [Planned, Cancelled, EnteredInError];
}

// The HL7 v3 encounter class codes this clinic uses.
public static class EncounterClass
{
    public const string Ambulatory = "AMB";

    public const string Emergency = "EMER";

    public const string Home = "HH";

    public const string Inpatient = "IMP";

    public const string Virtual = "VR";
}
